  border: 1px solid #bfd6e1;
  background: #ecf5f7;
  width: 27px;
  height: 27px;
  border-radius: 100%;
  text-align: center;
  font-size: 10px;
  line-height: 25px;
}
.timeline b {
  font-weight: 500;
  font-size: 13px;
}
.timeline small {
  display: block;
  font-size: 11px;
  color: var(--muted);
}
.timeline button {
  border: 0;
  background: none;
  color: var(--teal);
  padding: 0;
  font-size: 11px;
}
.provenance {
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: 30px;
  padding: 24px 2px;
  font-size: 11px;
  color: var(--muted);
}
.provenance code {
  display: block;
  font-size: 10px;
  margin-top: 6px;
  overflow-wrap: anywhere;
}
.provenance a {
  display: block;
  margin-top: 7px;
}
.provenance p {
  margin-top: 7px;
  line-height: 1.6;
}
details {
  padding: 15px 18px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #f8fafc;
  margin-bottom: 12px;
  font-size: 12px;
}
summary {
  cursor: pointer;
  color: var(--ink);
  font-weight: 500;
}
pre {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  background: #eef3f9;
  border: 1px solid #d9e4ee;
  padding: 12px;
  border-radius: 4px;
  font-size: 11px;
  max-height: 350px;
  overflow: auto;
}
footer {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  border-top: 1px solid var(--line);
  padding-top: 22px;
  margin-top: 30px;
  font-size: 10px;
  color: var(--muted);
}
table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  text-align: left;
}
td,
th {
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
}
th {
  font-weight: 500;
  color: var(--muted);
  background: #f8fafc;
}
.bridge {
  display: flex;
  gap: 9px;
  flex-wrap: wrap;
}
.bridge > div {
  flex: 1;
  background: #f0f5fa;
  border: 1px solid var(--line);
  padding: 15px;
  border-radius: 5px;
}
.bridge strong {
  display: block;
  font-size: 23px;
  font-weight: 500;
}
.bridge small {
  display: block;
  color: var(--muted);
}
.artifact-select {
  margin-bottom: 12px;
}
.comparison {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.comparison section {
  border: 1px solid var(--line);
  padding: 14px;
  border-radius: 5px;
  font-size: 12px;
}
.comparison h3 {
  font-size: 13px;
  margin: 0 0 8px;
}
.row-select {
  margin-bottom: 15px;
  max-width: 400px;
}
#fresh {
  border: 1px solid var(--teal);
  padding: 8px 12px;
  border-radius: 4px;
  background: var(--teal);
  color: #fff;
}
#import {
  display: block;
  margin: 10px 0;
}
.empty {
  padding: 30px;
  color: var(--muted);
  border: 1px dashed var(--line);
  border-radius: 5px;
}
@media (min-width: 1600px) {
  main {
    padding-top: 55px;
  }
  .intro {
    margin-bottom: 45px;
  }
  h1 {
    font-size: 47px;
  }
}
@media (max-width: 1100px) {
  .sidebar {
    width: 215px;
    padding: 26px 16px;
  }
  .workspace {
    margin-left: 215px;
  }
  header {
    padding: 0 26px;
  }
  main {
    padding: 30px 26px;
  }
  .toolbar {
    flex-wrap: wrap;
  }
  .toolbar > div {
    min-width: 100%;
  }
  .intro {
    gap: 25px;
  }
  h1 {
    font-size: 33px;
  }
  .comparison {
    grid-template-columns: 1fr;
  }
  .metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 760px) {
  .sidebar {
    position: static;
    width: 100%;
    height: auto;
    padding: 18px;
  }
  .brand {
    margin-bottom: 15px;
  }
  .sidebar-label,
  .sidebar-bottom {
    display: none;
  }
  nav {
    display: flex;
    gap: 6px;
  }
  .nav-item {
    margin: 0;
    padding: 10px 8px;
    font-size: 11px;
  }
  .nav-item small {
    display: none;
  }
  .nav-item > span {
    display: none;
  }
  .workspace {
    margin-left: 0;
  }
  header {
    height: 55px;
    padding: 0 18px;
  }
  .breadcrumb {
    font-size: 8px;
    display: flex;
    flex-direction: column;
    gap: 2px;
    letter-spacing: 0.7px;
    min-width: 0;
    line-height: 1.5;
  }
  .breadcrumb span {
    display: none;
  }
  header {
    gap: 12px;
  }
  .recording-badge {
    font-size: 8px;
    flex-shrink: 0;
    white-space: nowrap;
    letter-spacing: 0.5px;
    padding: 6px 8px;
  }
  main {
    padding: 25px 18px;
  }
  .intro {
    grid-template-columns: 1fr;
    gap: 20px;
  }
  .principle {
    display: none;
  }
  h1 {
    font-size: 33px;
  }
  .metrics {
    grid-template-columns: repeat(2, 1fr);
  }
  .toolbar {
    gap: 8px;
  }
  .primary,
  .button {
    flex: 1;
    text-align: center;
    font-size: 10px !important;
  }
  .tabs {
    gap: 10px;
    padding: 0 12px;
    overflow: auto;
  }
  .tabs button {
    white-space: nowrap;
    font-size: 11px;
  }
  .case-heading {
    padding: 18px;
    align-items: flex-start;
  }
  .tag {
    white-space: normal;
    text-align: center;
  }
  #panel {
    padding: 18px;
  }
  .columns,
  .provenance {
    grid-template-columns: 1fr;
  }
  .metric {
    padding: 12px;
  }
  .metric strong {
    font-size: 20px;
  }
  footer {
    flex-direction: column;
  }
  .skip {
    left: 20px;
  }
  table {
    display: block;
    overflow: auto;
  }
}

/* GTM investigation: retain the Lab palette and expose each independent boundary. */
.integrity-investigation { min-width:0; }
.integrity-investigation > details { margin-top:28px; }
.integrity-investigation a { text-decoration:underline; overflow-wrap:anywhere; }
.integrity-investigation pre { max-height:350px; overflow:auto; font-size:11px; }
.integrity-investigation pre:focus-visible { outline:3px solid #966316; outline-offset:3px; }
.integrity-investigation details { margin:16px 0; }
.integrity-investigation summary { cursor:pointer; color:#285c70; }
.integrity-amounts { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:12px; margin:18px 0 24px; }
.integrity-amounts > div { padding:18px 14px; border:1px solid #426078; background:#173148; color:#d1dfeb; border-radius:7px; }
.integrity-amounts small,.integrity-amounts strong,.integrity-amounts span { display:block; }
.integrity-amounts strong { color:#fff; font-size:clamp(20px,2vw,29px); margin:8px 0; letter-spacing:-.6px; }
.integrity-amounts small { font-size:12px; color:#d1dfeb; }
.integrity-amounts span { font-size:10px; color:#c3d5e3; }
.integrity-chain { display:grid; gap:18px; margin:22px 0; min-width:0; }
.integrity-chain > section { border-left:3px solid #32777e; padding-left:18px; min-width:0; }
.integrity-journey { padding-left:25px; }
.integrity-journey li { padding:14px 10px; border-bottom:1px solid var(--line); }
.integrity-stages button { min-height:62px; }
@media(max-width:1050px) { .integrity-amounts { grid-template-columns:repeat(2,minmax(0,1fr)); } }
@media(max-width:520px) { .integrity-amounts { gap:8px; } .integrity-amounts > div { padding:12px 9px; } .integrity-amounts strong { font-size:20px; } .integrity-chain > section { padding-left:10px; } }
.gtm-lanes { display:flex; flex-wrap:wrap; gap:8px; margin:18px 0 26px; }
.gtm-lanes a { border:1px solid var(--line); border-radius:5px; padding:10px 12px; font-size:12px; }
.gtm-lanes a[aria-current] { background:var(--nav); color:#fff; }
.gtm-origin { display:grid; gap:5px; margin:14px 0; overflow-wrap:anywhere; }
.gtm-origin small, table caption { color:var(--muted); font-size:11px; text-align:left; }
.gtm-origin code { font-size:10px; overflow-wrap:anywhere; }
#gtm-account, #gtm-model, #gtm-request { margin:8px 0 20px; }
.gtm-investigation > section { margin-top:25px; }
.gtm-investigation td small { display:block; overflow-wrap:anywhere; }
.gtm-investigation .columns > section { min-width:0; }
@media(max-width:760px) { .gtm-lanes a { flex:1 1 100%; } }

.gtm-journey { padding:16px; border-left:3px solid var(--teal); background:#f0f6f8; color:var(--ink); font-weight:500; }
.gtm-boundary { font-size:12px; color:var(--muted); line-height:1.7; }
.gtm-failures { display:flex; flex-wrap:wrap; gap:8px; margin:0 0 20px; }
.gtm-failures button { min-height:44px; padding:8px 12px; background:#f8fafc; border:1px solid var(--line); border-radius:5px; color:var(--ink); font-size:12px; }

/* Research case only: existing investigations keep their established surfaces. */
.research-case { min-width:0; }
.research-case a { text-decoration:underline; }
.research-case small { overflow-wrap:anywhere; }
.research-hero { background:var(--nav); color:#e5edf5; padding:28px; border-radius:10px; border:1px solid #385469; margin:24px 0; }
.research-hero h2 { color:#fff; font-size:28px; margin:8px 0; letter-spacing:-.5px; }
.research-hero p { max-width:780px; }
.research-hero small { color:#b7cbdc; }
.research-eyebrow { color:#a5d5d7; font-size:11px; font-weight:700; letter-spacing:1.5px; }
.research-layout { display:grid; grid-template-columns:245px minmax(0,1fr); gap:26px; align-items:start; }
.research-layout > *, .research-case .columns > * { min-width:0; }
.research-account { display:flex; flex-direction:column; text-align:left; width:100%; gap:5px; padding:14px; margin:0 0 9px; border:1px solid var(--line); border-radius:7px; background:#f7f9fc; color:var(--ink); min-height:88px; }
.research-account span { font-size:12px; }
.research-account small { color:#526779; font-size:11px; }
.research-account[aria-pressed=true] { background:#19374b; border-color:#34777e; color:#fff; }
.research-account[aria-pressed=true] small { color:#bfdade; }
.research-controls { display:grid; gap:7px; background:#f0f4f8; padding:16px; border-radius:7px; }
.research-controls select { width:100%; min-width:0; min-height:44px; font-size:13px; }
.research-controls label { color:#42596d; font-size:12px; font-weight:600; }
.research-selection { color:#40596e; font-size:12px; }
.research-source { padding:15px 0; border-top:1px solid var(--line); }
.research-source h4 { margin:0 0 8px; }
.research-source small { display:block; color:#526779; overflow-wrap:anywhere; }
.research-case blockquote { margin:10px 0; padding:12px 15px; border-left:3px solid var(--teal); background:#f0f5f7; }
.research-case .research-opening { background:#eaf3f4; font-size:16px; font-weight:500; }
.research-case pre, .research-case code { white-space:pre-wrap; overflow-wrap:anywhere; max-width:100%; font-size:11px; }
.research-case > section { margin-top:28px; padding-top:20px; border-top:1px solid var(--line); }
.research-state { display:inline-block; padding:7px 10px; border:1px solid #b3c9ce; border-radius:5px; color:#235960; background:#eaf3f4; font-size:10px; letter-spacing:.6px; font-weight:700; }
.research-rounds { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }
.research-rounds > div { padding:16px; background:#f0f4f8; border:1px solid var(--line); border-radius:7px; }
.research-rounds small { color:#526779; }
@media(max-width:1100px) { .research-layout { grid-template-columns:1fr; } .research-queue { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:9px; } .research-queue > h3,.research-queue > p,.research-queue > details { grid-column:1/-1; } }
@media(max-width:520px) { .research-hero { padding:19px; } .research-hero h2 { font-size:24px; } .research-queue,.research-rounds { grid-template-columns:1fr; } }

